using System;
using System.Collections.Generic;
using System.Linq;
using STP.Application;

namespace STP.Infrastructure.Content
{
    /// <summary>Closed complete production/fixture campaign graph using the existing catalog-set projection.</summary>
    public sealed class RuntimeProgressCatalog
    {
        private sealed class View:ILockedCampaignCatalog
        {
            internal View(CatalogIdentity identity,LockedCampaignEntry[] entries){Identity=identity;Entries=Array.AsReadOnly(entries);}
            public CatalogIdentity Identity{get;}public IReadOnlyList<LockedCampaignEntry> Entries{get;}
            public bool TryGet(PublicPuzzleIdentity identity,out LockedCampaignEntry? value){value=Entries.SingleOrDefault(e=>e.Puzzle.Equals(identity));return value!=null;}
        }
        public RuntimeProgressCatalog(IPublicPuzzleCatalog corpus,byte[] campaign,CatalogIdentity expectedCampaign,RuntimeCompletionCatalog completion,ICanonicalJson json)
        {
            if(corpus==null||expectedCampaign==null||completion==null||json==null)throw new ArgumentNullException();StarSource.Require((corpus.Identity.Use==CatalogUse.Production||corpus.Identity.Use==CatalogUse.ContractTest)&&expectedCampaign.Use==corpus.Identity.Use&&completion.Identity.Use==corpus.Identity.Use&&completion.SubjectKind=="LEVEL","STAR_CATALOG_USE_MISMATCH");var v=StarSource.Parse(campaign);StarSource.Fields(v,"schemaVersion","catalogId","catalogRevision","approvalStatus","seasons");StarSource.Require(StarSource.N(v,"schemaVersion")==2,"STAR_CAMPAIGN_SCHEMA_UNSUPPORTED");StarSource.Expected(v,expectedCampaign);
            string[] Unlock(JsonValue x){StarSource.Fields(x,"kind","requiredSubjectIds");string kind=StarSource.S(x,"kind");var ids=StarSource.A(x,"requiredSubjectIds").Select(StarSource.S).ToArray();StarSource.Require(ids.Distinct(StringComparer.Ordinal).Count()==ids.Length&&(kind=="ALWAYS"?ids.Length==0:kind=="ALL_FIRST_CLEARS"&&ids.Length>0),"STAR_UNLOCK_INVALID");return ids;}
            var rows=new List<(PublicPuzzleIdentity Identity,string Section,string Route,int Order,string[] Required)>();var subjects=new HashSet<string>(StringComparer.Ordinal){"S1"};var seasons=StarSource.A(v,"seasons");StarSource.Require(seasons.Count==1,"STAR_CAMPAIGN_MEMBERSHIP_INVALID");var s=seasons[0];StarSource.Fields(s,"id","order","titleKey","unlock","sections");StarSource.Require(StarSource.S(s,"id")=="S1"&&StarSource.N(s,"order")==1,"STAR_CAMPAIGN_ORDER_INVALID");StarSource.Key(StarSource.S(s,"titleKey"));var sr=Unlock(StarSource.Get(s,"unlock"));var sections=StarSource.A(s,"sections");StarSource.Require(sections.Count==5,"STAR_CAMPAIGN_MEMBERSHIP_INVALID");
            for(int si=0;si<5;si++){var section=sections[si];StarSource.Fields(section,"id","order","titleKey","unlock","routes");string sid="S1-"+(si+1).ToString("D2");StarSource.Require(StarSource.S(section,"id")==sid&&StarSource.N(section,"order")==si+1&&subjects.Add(sid),"STAR_CAMPAIGN_ORDER_INVALID");StarSource.Key(StarSource.S(section,"titleKey"));var nr=sr.Concat(Unlock(StarSource.Get(section,"unlock"))).ToArray();var routes=StarSource.A(section,"routes");StarSource.Require(routes.Count==4,"STAR_CAMPAIGN_MEMBERSHIP_INVALID");for(int ri=0;ri<4;ri++){var route=routes[ri];StarSource.Fields(route,"id","order","titleKey","unlock","levels");string rid=sid+"-"+(ri+1).ToString("D2");StarSource.Require(StarSource.S(route,"id")==rid&&StarSource.N(route,"order")==ri+1&&subjects.Add(rid),"STAR_CAMPAIGN_ORDER_INVALID");StarSource.Key(StarSource.S(route,"titleKey"));var rr=nr.Concat(Unlock(StarSource.Get(route,"unlock"))).ToArray();var levels=StarSource.A(route,"levels");StarSource.Require(levels.Count==12,"STAR_CAMPAIGN_MEMBERSHIP_INVALID");for(int li=0;li<12;li++){var level=levels[li];StarSource.Fields(level,"puzzleId","order","unlock");string id=rid+"-"+(li+1).ToString("D2");StarSource.Require(StarSource.S(level,"puzzleId")==id&&StarSource.N(level,"order")==li+1&&subjects.Add(id),"STAR_CAMPAIGN_ORDER_INVALID");var puzzle=corpus.Puzzles.SingleOrDefault(p=>p.Identity.PuzzleId==id);StarSource.Require(puzzle!=null,"STAR_CAMPAIGN_IDENTITY_MISMATCH");rows.Add((puzzle!.Identity,sid,rid,li+1,rr.Concat(Unlock(StarSource.Get(level,"unlock"))).ToArray()));}}}
            StarSource.Require(rows.Count==240&&corpus.Puzzles.Count==240,"STAR_CAMPAIGN_MEMBERSHIP_INVALID");string[] Expand(string subject){StarSource.Require(subjects.Contains(subject),"STAR_UNLOCK_REFERENCE_MISSING");return rows.Where(r=>subject=="S1"||r.Section==subject||r.Route==subject||r.Identity.PuzzleId==subject).Select(r=>r.Identity.PuzzleId).ToArray();}
            var entries=rows.Select(r=>new LockedCampaignEntry(expectedCampaign,r.Identity,"S1",r.Section,r.Route,r.Order,r.Required.SelectMany(Expand).Distinct(StringComparer.Ordinal).OrderBy(x=>x,StringComparer.Ordinal).ToArray())).ToArray();
            var done=new HashSet<string>(StringComparer.Ordinal);void Visit(string id,HashSet<string> path){if(done.Contains(id))return;StarSource.Require(path.Add(id),"STAR_UNLOCK_CYCLE");foreach(string required in entries.Single(e=>e.Puzzle.PuzzleId==id).RequiredFirstClears)Visit(required,path);path.Remove(id);done.Add(id);}foreach(var entry in entries)Visit(entry.Puzzle.PuzzleId,new HashSet<string>(StringComparer.Ordinal));
            Campaign=new View(expectedCampaign,entries);Completion=completion;string projection="{\"publicCatalog\":"+LocalSaveHash.CatalogProjection(corpus.Identity)+",\"campaignCatalog\":"+LocalSaveHash.CatalogProjection(expectedCampaign)+",\"completionCatalog\":"+LocalSaveHash.CatalogProjection(completion.Identity)+"}";string aggregateId=corpus.Identity.Use==CatalogUse.ContractTest?"fixture-calibrated-catalog-set":"production-s1-catalog-set";var aggregate=new CatalogIdentity(aggregateId,1,LocalSaveHash.Bytes(LocalSaveHash.Canonical(json,projection)),corpus.Identity.Use,corpus.Identity.ApprovalStatus);CatalogSet=CatalogSetIdentity.Create(corpus.Identity,expectedCampaign,completion.Identity,aggregate,json);
        }
        public ILockedCampaignCatalog Campaign{get;}public RuntimeCompletionCatalog Completion{get;}public CatalogSetIdentity CatalogSet{get;}
    }
}
